import React from 'react';
import {
  documentToReactComponents,
  type Options,
} from '@contentful/rich-text-react-renderer';
import {
  BLOCKS,
  INLINES,
  MARKS,
  type Document,
} from '@contentful/rich-text-types';
import type { Theme } from '../types';

interface RichTextProps {
  raw?: string | null;
  t: Theme;
}

export function RichText({ raw, t }: RichTextProps) {
  if (!raw) return null;

  let document: Document;
  try {
    document = JSON.parse(raw) as Document;
  } catch {
    return null;
  }

  const options: Options = {
    renderMark: {
      [MARKS.BOLD]: (children) => (
        <strong style={{ color: t.text, fontWeight: 600 }}>{children}</strong>
      ),
      [MARKS.ITALIC]: (children) => (
        <em style={{ color: t.text2 }}>{children}</em>
      ),
      [MARKS.CODE]: (children) => (
        <code
          style={{
            fontFamily: 'DM Mono, monospace',
            fontSize: '0.875em',
            background: t.chipBg,
            border: `1px solid ${t.border}`,
            borderRadius: 4,
            padding: '2px 6px',
            color: t.purple,
          }}
        >
          {children}
        </code>
      ),
    },
    renderNode: {
      [BLOCKS.PARAGRAPH]: (_node, children) => (
        <p
          style={{
            margin: '0 0 14px 0',
            color: t.text2,
            fontSize: 14,
            lineHeight: 1.85,
            fontFamily: 'DM Mono, monospace',
          }}
        >
          {children}
        </p>
      ),
      [BLOCKS.HEADING_1]: (_node, children) => (
        <h1
          style={{
            margin: '24px 0 10px 0',
            fontFamily: 'Syne, sans-serif',
            fontSize: 32,
            fontWeight: 700,
            letterSpacing: '-0.02em',
            color: t.text,
          }}
        >
          {children}
        </h1>
      ),
      [BLOCKS.HEADING_2]: (_node, children) => (
        <h2
          style={{
            margin: '20px 0 8px 0',
            fontFamily: 'Syne, sans-serif',
            fontSize: 24,
            fontWeight: 600,
            letterSpacing: '-0.02em',
            color: t.text,
          }}
        >
          {children}
        </h2>
      ),
      [BLOCKS.HEADING_3]: (_node, children) => (
        <h3
          style={{
            margin: '16px 0 6px 0',
            fontFamily: 'Syne, sans-serif',
            fontSize: 18,
            fontWeight: 600,
            color: t.text,
          }}
        >
          {children}
        </h3>
      ),
      [BLOCKS.HEADING_4]: (_node, children) => (
        <h4
          style={{
            margin: '14px 0 6px 0',
            fontFamily: 'Syne, sans-serif',
            fontSize: 15,
            fontWeight: 600,
            color: t.text,
          }}
        >
          {children}
        </h4>
      ),
      [BLOCKS.UL_LIST]: (_node, children) => (
        <ul
          style={{
            margin: '0 0 14px 0',
            paddingLeft: 22,
            color: t.text2,
            fontSize: 14,
            lineHeight: 1.85,
            fontFamily: 'DM Mono, monospace',
          }}
        >
          {children}
        </ul>
      ),
      [BLOCKS.OL_LIST]: (_node, children) => (
        <ol
          style={{
            margin: '0 0 14px 0',
            paddingLeft: 22,
            color: t.text2,
            fontSize: 14,
            lineHeight: 1.85,
            fontFamily: 'DM Mono, monospace',
          }}
        >
          {children}
        </ol>
      ),
      [BLOCKS.LIST_ITEM]: (_node, children) => (
        <li style={{ marginBottom: 6 }}>{children}</li>
      ),
      [BLOCKS.QUOTE]: (_node, children) => (
        <blockquote
          style={{
            margin: '0 0 14px 0',
            padding: '12px 18px',
            borderLeft: `3px solid ${t.purple}`,
            background: t.chipBg,
            borderRadius: '0 6px 6px 0',
            color: t.text2,
            fontStyle: 'italic',
            fontSize: 14,
            lineHeight: 1.85,
            fontFamily: 'DM Mono, monospace',
          }}
        >
          {children}
        </blockquote>
      ),
      [BLOCKS.HR]: () => (
        <hr
          style={{
            margin: '20px 0',
            border: 'none',
            borderTop: `1px solid ${t.border}`,
          }}
        />
      ),
      [INLINES.HYPERLINK]: (node, children) => {
        const uri = (node.data as { uri?: string }).uri ?? '#';
        return (
          <a
            href={uri}
            target='_blank'
            rel='noopener noreferrer'
            style={{
              color: t.purple,
              textDecoration: 'underline',
              textUnderlineOffset: 3,
            }}
          >
            {children}
          </a>
        );
      },
    },
  };

  return (
    <div style={{ margin: '0 0 24px 0' }}>
      {documentToReactComponents(document, options)}
    </div>
  );
}
