import React from 'react';
import { GatsbyImage, type IGatsbyImageData } from 'gatsby-plugin-image';
import type { Theme } from '../types';
import { RichText } from './RichText';

export interface ContentfulAsset {
  title?: string | null;
  description?: string | null;
  gatsbyImageData?: IGatsbyImageData;
}

export interface ContentfulProject {
  id: string;
  sku?: string | null;
  title?: string | null;
  introduction?: string | null;
  price?: string | null;
  description?: {
    raw?: string | null;
  } | null;
  headerImage?: {
    gatsbyImageData?: IGatsbyImageData;
  } | null;
  gallery?: Array<ContentfulAsset | null> | null;
}

const IMAGE_FRAME_RATIO = '16 / 9';

export function ContentfulProjectDetails({
  project,
  t,
}: {
  project: ContentfulProject;
  t: Theme;
}) {
  const headerImageData = project.headerImage?.gatsbyImageData;
  const gallery = (project.gallery ?? []).filter(
    (asset): asset is ContentfulAsset => Boolean(asset),
  );
  const title = project.title || project.sku || 'Project';

  return (
    <article
      style={{
        border: `1px solid ${t.border}`,
        borderRadius: 10,
        background: t.surface,
        padding: 28,
      }}
    >
      <h1
        style={{
          margin: '0 0 12px 0',
          fontFamily: 'Syne, sans-serif',
          fontSize: 'clamp(34px, 5vw, 56px)',
          lineHeight: 1,
          letterSpacing: '-0.03em',
          color: t.text,
        }}
      >
        {title}
      </h1>

      {project.introduction ? (
        <p
          style={{
            margin: '0 0 18px 0',
            color: t.text2,
            lineHeight: 1.8,
            fontFamily: 'DM Mono, monospace',
          }}
        >
          {project.introduction}
        </p>
      ) : null}

      {project.price ? (
        <div
          style={{
            marginBottom: 18,
            fontSize: 12,
            color: t.purple,
            letterSpacing: '0.06em',
            textTransform: 'uppercase',
            fontFamily: 'DM Mono, monospace',
          }}
        >
          {project.price}
        </div>
      ) : null}

      {headerImageData ? (
        <div
          style={{
            marginBottom: 22,
            borderRadius: 8,
            overflow: 'hidden',
            aspectRatio: IMAGE_FRAME_RATIO,
          }}
        >
          <GatsbyImage
            image={headerImageData}
            alt={title}
            style={{ width: '100%', height: '100%' }}
            imgStyle={{ objectFit: 'cover' }}
          />
        </div>
      ) : null}

      <RichText raw={project.description?.raw} t={t} />

      {gallery.length > 0 ? (
        <section>
          <h2
            style={{
              margin: '0 0 12px 0',
              fontFamily: 'Syne, sans-serif',
              fontSize: 24,
              color: t.text,
            }}
          >
            Gallery
          </h2>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))',
              gap: 12,
            }}
          >
            {gallery.map((asset, index) => {
              if (!asset.gatsbyImageData) return null;

              return (
                <div
                  key={asset.title || index}
                  style={{
                    borderRadius: 8,
                    overflow: 'hidden',
                    aspectRatio: IMAGE_FRAME_RATIO,
                  }}
                >
                  <GatsbyImage
                    image={asset.gatsbyImageData}
                    alt={asset.description || `${title} image ${index + 1}`}
                    style={{ width: '100%', height: '100%' }}
                    imgStyle={{ objectFit: 'cover' }}
                  />
                </div>
              );
            })}
          </div>
        </section>
      ) : null}
    </article>
  );
}
